define('parccTei/pciCreator/ims/fractionModelInteraction/runtime/libs/pieChart',[
    'taoQtiItem/portableLib/raphael',
    'taoQtiItem/portableLib/lodash'
], function(Raphael, _){

    'use strict';

    function getTotalSelected(selectedPartitions){
        return _.compact(_.values(selectedPartitions)).length;
    }

    /**
     *
     * @param {Array} selectedPartitions - e.g. [true, false, false, true, false, false]
     * @param {Object} config
     * @param {Object} [config.padding] - the padding of the pie chart
     * @param {Object} [config.radius] - the radius of the pie chart
     * @param {Object} [config.partitionColor] - the color of unseelcted slices
     * @param {Object} [config.selectedPartitionsColor] - the color of selected slices
     * @param {Object} [config.outlineColor]
     * @param {Object} [config.outlineThickness]
     * @param {Object} $container - jQuery object
     * @returns {undefined}
     */
    Raphael.fn.pieChart = function(selectedPartitions, config, $container){

        var paper = this,
            chart = this.set(),
            focusRing = null,
            skipFocusRingForPointerFocus = false,
            padding = config.padding || 2,
            r = parseInt(config.radius),
            // read some stuff from config & reformat datas
            cx = r + padding,
            cy = r + padding,
            // Math Constant
            rad = Math.PI / 180,
            getStyle = function(selected){
                return {
                    fill : selected ? config.selectedPartitionsColor : config.partitionColor,
                    cursor : 'pointer',
                    stroke : config.outlineColor,
                    'stroke-width' : config.outlineThickness
                };
            },
            setHoverStyle = function(raphaelObject){
                raphaelObject.hover(function(){
                    this.animate({
                        'fill-opacity' : 0.7
                    });
                }, function(){
                    this.stop().attr({
                        'fill-opacity' : 1
                    });
                });
            },
            clearFocusRing = function(){
                if(focusRing){
                    focusRing.remove();
                    focusRing = null;
                }
            },
            applyFocusRing = function(raphaelObject){
                clearFocusRing();
                focusRing = raphaelObject.clone();

                focusRing.attr({
                    fill : 'none',
                    stroke : '#005fcc',
                    'stroke-width' : 4,
                    'stroke-linejoin' : 'round',
                    cursor : 'default'
                });
                focusRing.node.setAttribute('pointer-events', 'none');
                focusRing.node.setAttribute('aria-hidden', 'true');
                focusRing.toFront();
            },
            isActivationKey = function(event){
                return event.key === 'Enter'
                    || event.key === ' '
                    || event.key === 'Space'
                    || event.key === 'Spacebar'
                    || event.code === 'Space'
                    || event.keyCode === 13
                    || event.keyCode === 32;
            },
            clearPointerFocusSuppression = function(){
                skipFocusRingForPointerFocus = false;
            },
            shouldShowFocusRing = function(node){
                if(skipFocusRingForPointerFocus){
                    skipFocusRingForPointerFocus = false;
                    return false;
                }
                return !node.matches || node.matches(':focus-visible');
            },
            makeInteractive = function(raphaelObject, index, selected){
                var toggle = getClickCallback(index);

                raphaelObject.node.setAttribute('tabindex', '0');
                raphaelObject.node.setAttribute('role', 'checkbox');
                raphaelObject.node.setAttribute('aria-label', `Pie slice ${index + 1} of ${selectedPartitions.length}`);
                raphaelObject.node.setAttribute('aria-checked', selected ? 'true' : 'false');
                raphaelObject.click(toggle);
                raphaelObject.node.addEventListener('focus', function(){
                    if(shouldShowFocusRing(raphaelObject.node)){
                        applyFocusRing(raphaelObject);
                    }
                });
                raphaelObject.node.addEventListener('blur', function(){
                    clearFocusRing();
                });
                raphaelObject.node.addEventListener('pointerdown', function(){
                    skipFocusRingForPointerFocus = true;
                    clearFocusRing();
                });
                raphaelObject.node.addEventListener('pointerup', clearPointerFocusSuppression);
                raphaelObject.node.addEventListener('pointercancel', clearPointerFocusSuppression);
                raphaelObject.node.addEventListener('lostpointercapture', clearPointerFocusSuppression);
                raphaelObject.node.addEventListener('keydown', function(event){
                    if(isActivationKey(event)){
                        event.preventDefault();
                        toggle.call(raphaelObject);
                    }
                });
            };

        //work on a clone of the array to prevent external modification
        selectedPartitions = _.clone(selectedPartitions);

        /**
         * Create a new sector to draw
         * @param  {int}          cx            initial position x
         * @param  {int}          cy            initial position y
         * @param  {int}          r             radius
         * @param  {int}          startAngle    initial angle to start drawing
         * @param  {int}          endAngle      ending angle to stop drawing
         * @param  {object|array} params        params passed to Raphael .attr()
         * @return {object}                     Raphael path
         */
        function sector(cx, cy, r, startAngle, endAngle, params){
            var x1 = cx + r * Math.cos(-startAngle * rad),
                x2 = cx + r * Math.cos(-endAngle * rad),
                y1 = cy + r * Math.sin(-startAngle * rad),
                y2 = cy + r * Math.sin(-endAngle * rad);
            return paper.path(['M', cx, cy, 'L', x1, y1, 'A', r, r, 0, +(endAngle - startAngle > 180), 0, x2, y2, 'z']).attr(params);
        }

        var angle = 0,
            angleplus = 360 / selectedPartitions.length;

        /**
         * Iterational function that draw every slice
         * @param  {int} j slice number
         */
        function drawSlice(j){

            var p, selected = selectedPartitions[j];

            //modify the internal state
            selectedPartitions[j] = selected;

            // Slice , also called sector.
            p = sector(cx, cy, r, angle, angle + angleplus, getStyle(selected));

            //increase the andle
            angle += angleplus;

            //add hover style
            setHoverStyle(p);

            // Register this slice into the canvas
            chart.push(p);

            // Register events on the slice / sector
            makeInteractive(p, j, selected);
        }

        function drawCircle(){

            var c = paper.circle(cx, cy, r).attr(getStyle(selectedPartitions[0]));

            //add hover style
            setHoverStyle(c);

            // Register this slice into the canvas
            chart.push(c);

            // Register events on the slice / sector
            makeInteractive(c, 0, selectedPartitions[0]);
        }

        function getClickCallback(j){
            return function(){
                if(String(this.attrs.fill) === config.partitionColor){
                    //it is selected:

                    // Change the color of the background
                    this.attr(getStyle(true));
                    // update the internal state
                    selectedPartitions[j] = true;
                    this.node.setAttribute('aria-checked', 'true');
                    $container.trigger('select_slice.pieChart', [selectedPartitions, getTotalSelected(selectedPartitions)]);
                }else{

                    // Change the background color to the default unselected value
                    this.attr(getStyle(false));
                    // update the internal state
                    selectedPartitions[j] = false;
                    this.node.setAttribute('aria-checked', 'false');
                    $container.trigger('unselect_slice.pieChart', [selectedPartitions, getTotalSelected(selectedPartitions)]);
                }
            }
        }

        if(selectedPartitions.length > 1){
            for(var i = 0; i < selectedPartitions.length; i++){
                drawSlice(i);
            }
        }else{
            drawCircle();
        }

        $container.trigger('drawn.pieChart');
    };
});

